mapper.select:
SELECT COUNT(*)
FROM electronic_approval
WHERE approval_id = #{approvalId}

SELECT COUNT(*)
FROM electronic_approval
WHERE approval_id = #{approvalId}
  AND drafter_id = #{drafterId}

mapper.update:
UPDATE electronic_approval
SET approval_status = 'PENDING'
WHERE approval_id = #{approvalId}
  AND drafter_id = #{drafterId}
  AND approval_status = 'TEMP'

mapper.select:
SELECT title
FROM electronic_approval
WHERE approval_id = #{approvalId}

SELECT approval_status
FROM electronic_approval
WHERE approval_id = #{approvalId}

SELECT drafter_id
FROM electronic_approval
WHERE approval_id = #{approvalId}

mapper.update:
UPDATE electronic_approval
SET approval_status = 'REJECTED'
WHERE approval_id = #{approvalId}

UPDATE electronic_approval
SET approval_status = 'HOLD'
WHERE approval_id = #{approvalId}

UPDATE electronic_approval
SET read_dt = NOW()
WHERE approval_id = #{approvalId}
  AND read_dt IS NULL
  AND (
    drafter_id = #{employeeId}
    OR EXISTS (
        SELECT 1
        FROM approval_line al
        WHERE al.approval_id = #{approvalId}
          AND al.approver_id = #{employeeId}
    )
    OR EXISTS (
        SELECT 1
        FROM reference_line rf
        WHERE rf.approval_id = #{approvalId}
          AND rf.referencer_id = #{employeeId}
    )
    OR EXISTS (
        SELECT 1
        FROM recipient_line rc
        WHERE rc.approval_id = #{approvalId}
          AND rc.receiver_id = #{employeeId}
    )
  )

choose.when:
EXISTS (
    SELECT 1
    FROM reference_line rfi
    WHERE rfi.approval_id = ea.approval_id
      AND rfi.referencer_id = #{employeeId}
)

ea.approval_status = 'HOLD'
AND (
    ea.drafter_id = #{employeeId}
    OR EXISTS (
        SELECT 1
        FROM approval_line ali
        WHERE ali.approval_id = ea.approval_id
          AND ali.approver_id = #{employeeId}
    )
)

choose.otherwise:
(
    ea.approval_status = 'COMPLETE'
    AND EXISTS (
        SELECT 1
        FROM recipient_line rli
        WHERE rli.approval_id = ea.approval_id
          AND rli.receiver_id = #{employeeId}
    )
)
OR (
    ea.approval_status = 'REJECTED'
    AND ea.drafter_id = #{employeeId}
)
OR (
    ea.approval_status = 'COMPLETE'
    AND ea.drafter_id = #{employeeId}
)
OR (
    ea.approval_status = 'TEMP'
    AND ea.drafter_id = #{employeeId}
)
OR EXISTS (
    SELECT 1
    FROM reference_line rfi
    WHERE rfi.approval_id = ea.approval_id
      AND rfi.referencer_id = #{employeeId}
)
OR (
    ea.approval_status = 'HOLD'
    AND (
        ea.drafter_id = #{employeeId}
        OR EXISTS (
            SELECT 1
            FROM approval_line ali
            WHERE ali.approval_id = ea.approval_id
              AND ali.approver_id = #{employeeId}
        )
    )
)
